                        const filterParts = filterValue.split(',').map(v => v.trim());
                        const itemParts = itemStr.split(/[/,]/).map(v => v.trim());

                        return filterParts.some(fv => itemParts.includes(fv));
                    });
                });
            }

            // Redirect to College Detail page
            $scope.Each_Collage_Data = function (cm_id) {
                $.ajax({
                    type: "POST",
                    url: "Form_EBrochure.aspx/Get_Incrypt_Decrypt_College_ID",
                    contentType: 'application/json; charset=utf-8',
                    data: JSON.stringify({ cm_id: cm_id }),
                    datatype: "json",
                    beforeSend: function () {
                        $('[id*=UpdateProgress]').css('display', '');
                    },
                    success: function (response) {
                        if (response.d != "[]") {
                            window.open('EBrochure_College_Details.aspx?cm_id=' + response.d, '_blank');
                        }
                    },
                    error: function () {
                        alert('Some error occurred.');
                    },
                    complete: function () {
                        $('[id*=UpdateProgress]').css('display', 'none');
                    }
                });
            };

            // Fetch All Data
            $scope.GetData = function () {
                $("#preloader").show();
                $(document).ajaxSend(function (event, xhr, settings) {
                    xhr.setRequestHeader("X-menu-id", "-1");
                });
                $http({
                    method: 'POST',
                    async: true,
                    url: "Form_EBrochure.aspx/Bind_Form_EBrochure_All_Data",
                    data: {},
                }).then(
                    function (response) {
                        try {
                            if (response.data.d && response.data.d.toString() != '') {
                                var dataSet = JSON.parse(response.data.d);
                                $scope.Course_Binds = dataSet.Table || [];
                                $scope.universities = dataSet.Table1 || [];
                                $scope.collage_type = dataSet.Table2 || [];
                                $scope.College_GEN_hostel = dataSet.Table3 || [];
                                $scope.District_Bind = dataSet.Table4 || [];
                                $scope.College_NAAC = dataSet.Table6 || [];

                                if (!dataSet.Table5 || dataSet.Table5.length == 0) {
                                    alert("No College Records Found");
                                    $("#preloader").hide();
                                    return;
                                }

                                $scope.College_Details_all = dataSet.Table5;
                                $scope.College_Details = dataSet.Table5.slice(0, 50);
                                $scope.visibleCollegeCount = 50;
                                document.getElementById("Total_Counts").innerText = $scope.College_Details_all.length;

                                $scope.College_Details = $scope.College_Details.map(function (item) {
                                    item.Course = $sce.trustAsHtml(item.Course ? String(item.Course) : '');
                                    return item;
                                });
                                $scope.College_Details_all = $scope.College_Details_all.map(function (item) {
                                    item.Course = $sce.trustAsHtml(item.Course ? String(item.Course) : '');
                                    return item;
                                });

                                var allBranches = dataSet.Table7 || [];
                                angular.forEach($scope.Course_Binds, function (course) {
                                    course.isExpanded = false;
                                    course.Branches = allBranches.filter(function (branch) {
                                        return String(branch.dgre_id) === String(course.dgre_id);
                                    });
                                });
                            }
                        } catch (err) {
                            console.error("Error: ", err);
                        } finally {
                            $("#preloader").hide();
                        }
                    }
                );
            };

            $scope.Toggle_Branch_Panel = function (course) {
                course.isExpanded = !course.isExpanded;
            };

            $scope.Branch_Checkbox_Changed = function (course, branchId) {
                var anyBranchChecked = false;
                if (course.Branches && course.Branches.length > 0) {
                    anyBranchChecked = course.Branches.some(function (b) {
                        return $scope.BranchSelection && $scope.BranchSelection[b.bch_id] === true;
                    });
                }
                $scope.CourseSelection[course.dgre_id] = anyBranchChecked;

                document.getElementById("preloader").style.display = "block";

                let selectedBranchIDs = [];
                for (let bId in $scope.BranchSelection) {
                    if ($scope.BranchSelection[bId]) {
                        selectedBranchIDs.push(bId);
                    }
                }

                if (selectedBranchIDs.length > 0) {
                    $scope.filters.Branch_id = selectedBranchIDs.toString();
                } else {
                    $scope.filters.Branch_id = "";
                }

                let selectedCourseIDs = [];
                for (let cId in $scope.CourseSelection) {
                    if ($scope.CourseSelection[cId]) {
                        selectedCourseIDs.push(cId);
                    }
                }
                if (selectedCourseIDs.length > 0) {
                    $scope.filters.Course_id = selectedCourseIDs.toString();
                } else {
                    $scope.filters.Course_id = "";
                }

                $scope.College_Details_all_filtered = angular.copy(applyFilters($scope.College_Details_all, $scope.filters));

                var currentSearchText = $scope.searchText || "";
                if (currentSearchText.trim() !== "") {
                    $scope.College_Details_all_filtered = $scope.College_Details_all_filtered.filter(function (item) {
                        return item.College_Name.toLowerCase().includes(currentSearchText.toLowerCase());
                    });
                }

                $scope.College_Details = $scope.College_Details_all_filtered.slice(0, 50);
                $scope.visibleCollegeCount = 50;

                document.getElementById("Total_Counts").innerText = $scope.College_Details_all_filtered.length;
                $scope.Data_Changes();

                setTimeout(() => {
                    document.getElementById("preloader").style.display = "none";
                }, 200);
            };

            $scope.Degree_Checkbox_Changed = function (course) {
                var isDegreeChecked = $scope.CourseSelection[course.dgre_id];

                if (course.Branches && course.Branches.length > 0) {
                    angular.forEach(course.Branches, function (b) {
                        $scope.BranchSelection[b.bch_id] = isDegreeChecked;
                    });
                }

                $scope.Branch_Checkbox_Changed(course, null);
            };

            $scope.Auto_Expand_On_Search = function (searchText) {
                if (!searchText || searchText.trim() === "") {
                    angular.forEach($scope.Course_Binds, function (course) {
                        course.isExpanded = false;
                    });
                    return;
                }

                angular.forEach($scope.Course_Binds, function (course) {
                    var hasMatchingBranch = false;
                    if (course.Branches && course.Branches.length > 0) {
                        hasMatchingBranch = course.Branches.some(function (branch) {
                            return branch.bch_name.toLowerCase().includes(searchText.toLowerCase());
                        });
                    }

                    if (hasMatchingBranch) {
                        course.isExpanded = true;
                    }
                });
            };

            $scope.Filter_Degrees_And_Branches = function (searchText) {
                return function (course) {
                    if (!searchText || searchText.trim() === "") return true;

                    var searchLower = searchText.toLowerCase();
                    var degreeMatches = course.dgre_short_name.toLowerCase().includes(searchLower);

                    var branchMatches = false;
                    if (course.Branches && course.Branches.length > 0) {
                        branchMatches = course.Branches.some(function (branch) {
                            return branch.bch_name.toLowerCase().includes(searchLower);
                        });
                    }

                    return degreeMatches || branchMatches;
                };
            };
        });
    </script>
</body>
</html>
